```cpp
#include <string>
#include <iostream>
#include <sstream>

// Función que convierte texto con formato markdown a HTML
std::string markdownToHtml(const std::string& markdown) {
    std::stringstream html;

    // Caracteres especiales para convertir
    std::string markdown_chars = "\\`*_{}[]()>#+-.!";
    std::string html_tags = " \t\n`*_{}[]()>#+-.!";

    // Reemplazar caracteres especiales por sus correspondientes etiquetas HTML
    for (std::size_t I = 0; I < markdown_chars.size(); ++i) {
        html << markdown.replace(std::string(1, markdown_chars[i]), html_tags[i], "");
    }

    // Etiquetas HTML específicas para Markdown
    std::string headers[] = {"#", "##", "###", "####", "#####", "######"};
    std::string header_tags[] = {"h1", "h2", "h3", "h4", "h5", "h6"};

    // Reemplazar encabezados con sus correspondientes etiquetas HTML
    for (std::size_t I = 0; I < headers.size(); ++i) {
        std::string header_pattern = std::string(1, headers[i]) + "(.*)";
        std::string header_tag = header_tags[i];
        std::string header_replacement = std::string("<") + header_tag + std::string(">") + "\\1</") + header_tag + std::string(">");
        html << std::regex_replace(markdown, std::regex(header_pattern), header_replacement);
    }

    // Etiqueta para párrafo
    std::string paragraph_tag = "<p>";

    // Reemplazar líneas en blanco con etiquetas HTML para párrafo
    std::string line_break = "\n";
    html << std::regex_replace(markdown, std::regex("\\n\\n"), paragraph_tag + paragraph_tag);

    // Reemplazar líneas en blanco dentro de párrafos con una etiqueta HTML para línea en blanco
    html << std::regex_replace(markdown, std::regex("\\n"), "<br>");

    // Cerrar etiqueta de párrafo
    html << "</p>";

    // Devolver el texto en formato HTML
    return html.str();
}

int main() {
    std::string markdown = "Este es un **texto con formato** en #Markdown\n\nY esta es una línea en blanco.\n\nY otra línea en blanco.";

    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;

    return 0;
}
```

Esta función utiliza la librería estandar `std::stringstream` para crear el texto en formato HTML a partir del texto en formato Markdown. Los caracteres especiales se reemplazan por sus correspondientes etiquetas HTML, los encabezados se reemplazan por sus correspondientes etiquetas HTML, se agregan etiquetas HTML para párrafos y líneas en blanco, y se cierra la etiqueta de párrafo al final.

